const FLOW = 'https://vclwmydunloeqomsmaah.supabase.co/functions/v1/api-v1';
const FH = { Authorization: '***REMOVIDO***', 'Content-Type': 'application/json' };
const r = await this.helpers.httpRequest({ method: 'GET', url: FLOW + '/leads/9a6ea07f-1625-48b9-8625-2baa73d4e1b0/contacts', headers: FH, json: true });
const out = [];
for (const c of (r.items || [])) {
  if (/smits/i.test(c.name || '')) {
    await this.helpers.httpRequest({ method: 'PATCH', url: FLOW + '/contacts/' + c.id, headers: FH, json: true, body: { contato_status: 'nao_contatar', contato_status_motivo: 'Lusha trouxe pessoa de outra empresa com nome parecido (Holanda) - não é da BSM Solutions', contato_status_em: new Date().toISOString() } });
  }
  out.push({ json: { nome: c.name, cargo: c.cargo, whatsapp: c.whatsapp, email: c.email, linkedin: c.linkedin, status: c.contato_status } });
}
return out;
